import{_ as r,a as n,b as d,c as g,d as c,e as h,f as m,g as p,h as u,i as y,j as f,k as _,l as w,m as b,n as x,o as k,p as v,q as z,r as P,s as C,t as q,u as A,v as S,w as j,x as I,y as M,z as E,A as L,B,C as O,D,E as T,F as R,G as H,H as U,I as G,J as N,K,L as l,M as W,N as X,O as F,P as Z,Q,R as V,S as J,T as Y,U as $,V as tt,W as et,X as it,Y as ot,Z as at,$ as st,a0 as nt,a1 as lt,a2 as rt,a3 as dt,a4 as gt,a5 as ct,a6 as ht,a7 as i}from"./chunks/100.Z331kcEK.js";import{_ as e,a as mt}from"./chunks/3.DXyrffa9.js";import{_ as pt,a as ut,b as yt,c as o,d as ft,e as _t,f as wt,g as bt,h as a}from"./chunks/0.B6DNk-jR.js";import{_ as xt,o as kt,c as vt,ak as zt}from"./chunks/framework.hGPziE3B.js";const Pt="/projects/LargeModelKit/en/latest/assets/18.Be0YhmXG.webp",Ct="/projects/LargeModelKit/en/latest/assets/16.B0SzEvTh.webp",qt="/projects/LargeModelKit/en/latest/assets/17.gD4WXimG.webp",At="/projects/LargeModelKit/en/latest/assets/1.1.FHee5A7R.webp",St="/projects/LargeModelKit/en/latest/assets/1.2.BcrJgfRG.webp",jt="/projects/LargeModelKit/en/latest/assets/1.3.BRWb8INr.webp",It="/projects/LargeModelKit/en/latest/assets/1.4.GtsXbiAP.webp",Mt="/projects/LargeModelKit/en/latest/assets/2.0.BXpvm7Mp.webp",Et="/projects/LargeModelKit/en/latest/assets/2.1.spV0OpNX.webp",Lt="/projects/LargeModelKit/en/latest/assets/2.2.CsRwh8A0.webp",t="/projects/LargeModelKit/en/latest/assets/0.BuXsjdqo.webp",Bt="/projects/LargeModelKit/en/latest/assets/2.3.uDMbIL1N.webp",Ot="/projects/LargeModelKit/en/latest/assets/3.0.DkWTBpZh.webp",Dt="/projects/LargeModelKit/en/latest/assets/3.1.CnhA4-RX.webp",Tt="/projects/LargeModelKit/en/latest/assets/3.2.B-zWBZGO.webp",Rt="/projects/LargeModelKit/en/latest/assets/18.DbZ52dKE.webp",Ht="/projects/LargeModelKit/en/latest/assets/3.jJ7VsDnr.webp",Ut="/projects/LargeModelKit/en/latest/assets/8.UlJasyx8.webp",Gt="/projects/LargeModelKit/en/latest/assets/11.DJKOYMA4.webp",Nt="/projects/LargeModelKit/en/latest/assets/3.3.s2W7SYeB.webp",ee=JSON.parse('{"title":"2. Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2. Quick Start.md","filePath":"docs/2. Quick Start.md"}'),Kt={name:"docs/2. Quick Start.md"};function Wt(Xt,s,Ft,Zt,Qt,Vt){return kt(),vt("div",null,[...s[0]||(s[0]=[zt('<h1 id="_2-quick-start" tabindex="-1">2. <strong>Quick Start</strong> <a class="header-anchor" href="#_2-quick-start" aria-label="Permalink to &quot;2. **Quick Start**&quot;">​</a></h1><h2 id="_2-1-large-model-interactive-experience" tabindex="-1">2.1 <strong>Large Model Interactive Experience</strong> <a class="header-anchor" href="#_2-1-large-model-interactive-experience" aria-label="Permalink to &quot;2.1 **Large Model Interactive Experience**&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The WonderMind Module enables rapid hands-on exploration of diverse voice and vision AI capabilities. See <a href="./4. Software and Hardware Guide.html#section-4-4">4. Software and Hardware Guide / 4.4 WonderMind Module</a> for complete documentation.</strong></p></div><h3 id="_2-1-1-powering-on" tabindex="-1">2.1.1 <strong>Powering On</strong> <a class="header-anchor" href="#_2-1-1-powering-on" aria-label="Permalink to &quot;2.1.1 **Powering On**&quot;">​</a></h3><ol><li>Toggle the rear power switch. The screen illuminates, indicating successful startup.</li></ol><img loading="lazy" height="441" width="441" src="'+r+'" class="common_img" style="width:300px;"><ol start="2"><li>Upon power-up, the <strong>device hotspot name</strong> and <strong>browser configuration URL</strong> are displayed, with accompanying voice prompts. Complete <a href="#section-2-1-2">2.1.2 Module Network Setup</a> before proceeding.</li></ol><img loading="lazy" height="441" width="441" src="'+n+'" class="common_img" style="width:300px;"><p><a id="section-2-1-2"></a></p><h3 id="_2-1-2-module-network-setup" tabindex="-1">2.1.2 <strong>Module Network Setup</strong> <a class="header-anchor" href="#_2-1-2-module-network-setup" aria-label="Permalink to &quot;2.1.2 **Module Network Setup**&quot;">​</a></h3><ol><li>Network setup begins automatically after power-up. The <strong>device hotspot name</strong> and <strong>browser configuration URL</strong> are displayed on the screen, with accompanying voice prompts. The WonderMind Module activates its built-in hotspot for connection and configuration. Hotspot names vary by device, following the unified format <strong>WonderMind-xxxx</strong>. WonderMind-7885 serves as the example.</li></ol><img loading="lazy" height="441" width="441" src="'+n+'" class="common_img" style="width:300px;"><ol start="2"><li>Locate and connect to the corresponding hotspot via computer or mobile device. No password is required.</li></ol><img loading="lazy" height="186" width="356" src="'+d+'" class="common_img" style="width:400px;"><img loading="lazy" height="136" width="357" src="'+g+'" class="common_img" style="width:400px;"><ol start="3"><li>Click <a href="http://192.168.4.1/" target="_blank" rel="noreferrer">Network Configuration</a> to access the device network configuration URL directly. Alternatively, copy the URL below and open it in a browser.</li></ol><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">192.168</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.4.1</span></span></code></pre></div><img loading="lazy" height="546" width="1185" src="'+c+'" class="common_img" style="width:500px;"><ol start="4"><li>Enter the hotspot name for automatic connection on power-up in field ①. Enter the hotspot password in field ②. Finally, click in field ③ <strong>Connect</strong>. The module attempts to locate and connect to the matching hotspot using the configured credentials.</li></ol><img loading="lazy" height="244" width="1165" src="'+h+'" class="common_img" style="width:500px;"><ol start="5"><li>Available hotspots detected by the module are listed in the interface. Click an entry to auto-populate the corresponding hotspot name in field ①.</li></ol><img loading="lazy" height="224" width="375" src="'+m+'" class="common_img" style="width:500px;"><ol start="6"><li>If the following prompt appears on the interface, the hotspot is not detected or the password is incorrect. Re-enter the credentials.</li></ol><img loading="lazy" height="364" width="1163" src="'+p+'" class="common_img" style="width:500px;"><ol start="7"><li>If the following prompt appears on the interface, the module has located and connected to the hotspot. The module restarts and reconnects.</li></ol><img loading="lazy" height="304" width="640" src="'+u+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><strong>Do not enter hotspots that are undetected, weak, or lack internet access.</strong></li><li><strong>If a previous hotspot was saved, new credentials are stored alongside existing entries. On the next power-up, the module sequentially attempts each saved entry until a match is found.</strong></li><li><strong>If the following prompt is displayed after network configuration, Error: New version check failed. Retrying in xx seconds, the hotspot lacks internet access or has unstable connectivity. Switch to an alternative hotspot.</strong></li></ul></div><p><a id="section-2-1-3"></a></p><h3 id="_2-1-3-xiaozhi-ai-platform-authentication" tabindex="-1">2.1.3 XiaoZhi AI Platform Authentication <a class="header-anchor" href="#_2-1-3-xiaozhi-ai-platform-authentication" aria-label="Permalink to &quot;2.1.3 XiaoZhi AI Platform Authentication&quot;">​</a></h3><h4 id="_1-xiaozhi-ai-platform-account-login" tabindex="-1">(1) XiaoZhi AI Platform Account Login <a class="header-anchor" href="#_1-xiaozhi-ai-platform-account-login" aria-label="Permalink to &quot;(1) XiaoZhi AI Platform Account Login&quot;">​</a></h4><ol><li>Click <a href="https://xiaozhi.me/" target="_blank" rel="noreferrer">XiaoZhi AI Chatbot</a> to directly access the device binding URL. Alternatively, copy the URL below and open it in any browser.</li></ol><div class="language-py vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">py</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">xiaozhi.me</span></span></code></pre></div><img loading="lazy" height="410" width="960" src="'+y+'" class="common_img" style="width:500px;"><ol start="2"><li>Click <strong>Console</strong> to access the XiaoZhi AI Agent Management Platform.</li></ol><img loading="lazy" height="419" width="955" src="'+f+'" class="common_img" style="width:500px;"><ol start="3"><li>For an existing XiaoZhi AI Platform account, enter the credentials to login directly. For first-time login, register an account first.</li></ol><img loading="lazy" height="531" width="953" src="'+_+'" class="common_img" style="width:500px;"><ol start="4"><li>Fill in the required information, then click <strong>Send Code</strong> to receive the verification code required for account registration.</li></ol><img loading="lazy" height="526" width="957" src="'+w+'" class="common_img" style="width:500px;"><ol start="5"><li>Select the agreement and privacy policy checkbox, then click <strong>Login</strong>.</li></ol><img loading="lazy" height="532" width="956" src="'+b+'" class="common_img" style="width:500px;"><ol start="6"><li>Select and fill in the required information, then click <strong>Confirm</strong> to complete registration and login.</li></ol><img loading="lazy" height="542" width="958" src="'+x+'" class="common_img" style="width:500px;"><h4 id="_2-github-platform-login" tabindex="-1">(2) <strong>GitHub Platform Login</strong> <a class="header-anchor" href="#_2-github-platform-login" aria-label="Permalink to &quot;(2) **GitHub Platform Login**&quot;">​</a></h4><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><strong>Permission Differences. Authenticated and unauthenticated GitHub accounts have different permission levels, as shown below:</strong></li></ul><img loading="lazy" height="415" width="828" src="'+k+'" class="common_img" style="width:500px;"><ul><li><strong>If the permission differences are already understood, skip GitHub authentication and proceed to <a href="#section-2-1-4">2.1.4 Device Binding</a> after platform login. To proceed with GitHub authentication, follow the steps below.</strong></li></ul></div><ol><li>On the XiaoZhi AI Platform, click <strong>GitHub Verification</strong> below the<img loading="lazy" height="32" width="28" src="'+v+'" style="width:70px;" class="inline-icon"> icon. After the verification interface loads, click <strong>Link GitHub</strong>.</li></ol><img loading="lazy" height="419" width="1410" src="'+z+'" class="common_img" style="width:500px;"><img loading="lazy" height="762" width="1366" src="'+P+'" class="common_img" style="width:500px;"><ol start="2"><li>Wait for the page to redirect to the GitHub account sign-in page.</li></ol><img loading="lazy" height="697" width="522" src="'+C+'" class="common_img" style="width:500px;"><ol start="3"><li>If already registered with a GitHub account, log in directly with credentials and proceed to <a href="#section-2-1-3-3">2.1.3.3 Binding the XiaoZhi AI Platform and GitHub Platform</a>. If there is no GitHub account, click <strong>Create an account</strong>.</li></ol><img loading="lazy" height="697" width="522" src="'+q+'" class="common_img" style="width:500px;"><ol start="4"><li>Enter the email address, password, username, and location in the pop-up interface. Click <strong>Create account</strong> to submit the registration information.</li></ol><img loading="lazy" height="788" width="686" src="'+A+'" class="common_img" style="width:500px;"><ol start="5"><li>Click <strong>Visual puzzle</strong> in the page to start image verification.</li></ol><img loading="lazy" height="445" width="598" src="'+S+'" class="common_img" style="width:500px;"><ol start="6"><li>After image verification is completed, the GitHub platform sends a verification email to the previously entered registration email address. Open the email, copy the verification code, and enter it on the webpage.</li></ol><img loading="lazy" height="573" width="883" src="'+j+'" class="common_img" style="width:500px;"><img loading="lazy" height="392" width="691" src="'+I+'" class="common_img" style="width:500px;"><ol start="7"><li>After registration is completed, the webpage redirects to the login page, and a registration success notification pop-up is displayed.</li></ol><img loading="lazy" height="696" width="794" src="'+M+'" class="common_img" style="width:500px;"><p><a id="section-2-1-3-3"></a></p><h4 id="_3-binding-the-xiaozhi-ai-platform-and-github-platform" tabindex="-1">(3) Binding the XiaoZhi AI Platform and GitHub Platform <a class="header-anchor" href="#_3-binding-the-xiaozhi-ai-platform-and-github-platform" aria-label="Permalink to &quot;(3) Binding the XiaoZhi AI Platform and GitHub Platform&quot;">​</a></h4><ol><li>Click <strong>Authorize tenclass</strong> to complete binding the XiaoZhi AI Platform and GitHub.</li></ol><img loading="lazy" height="631" width="674" src="'+E+'" class="common_img" style="width:500px;"><ol start="2"><li>After binding is completed, XiaoZhi AI Platform authentication is fully completed. The page automatically returns to the previous authentication screen, and the following notification is displayed.</li></ol><img loading="lazy" height="759" width="1399" src="'+L+'" class="common_img" style="width:500px;"><p><a id="section-2-1-4"></a></p><h3 id="_2-1-4-device-binding" tabindex="-1">2.1.4 Device Binding <a class="header-anchor" href="#_2-1-4-device-binding" aria-label="Permalink to &quot;2.1.4 Device Binding&quot;">​</a></h3><ol><li>After completing XiaoZhi AI Platform registration, login, and authentication, click <strong>Agents</strong> to access the interface.</li></ol><img loading="lazy" height="274" width="1440" src="'+Pt+'" class="common_img" style="width:500px;"><ol start="2"><li>Click the dropdown arrow next to the Add Device button, then click <strong>Create Agent</strong>.</li></ol><img loading="lazy" height="259" width="939" src="'+B+'" class="common_img" style="width:500px;"><ol start="3"><li>Enter the agent name, then click <strong>Confirm</strong> to complete agent creation.</li></ol><img loading="lazy" height="275" width="530" src="'+O+'" class="common_img" style="width:500px;"><ol start="4"><li>Click <strong>Configure</strong> to access agent function settings.</li></ol><img loading="lazy" height="411" width="932" src="'+D+'" class="common_img" style="width:500px;"><ol start="5"><li>Click <strong>Role</strong> to configure the agent role. Select the desired conversation language in field ①, the desired voice in field ②, and configure voice settings in field ③.</li></ol><img loading="lazy" height="724" width="743" src="'+T+'" class="common_img" style="width:500px;"><ol start="6"><li>Click <strong>Model &amp; Memory</strong>. Select <strong>DeepSeek V4 (Rich Personality)</strong> for the language model. Disable the memory function. Keep other settings as default.</li></ol><img loading="lazy" height="726" width="759" src="'+Ct+'" class="common_img" style="width:500px;"><img loading="lazy" height="724" width="751" src="'+R+'" class="common_img" style="width:500px;"><ol start="7"><li>Click <strong>Extensions</strong>. Enable all official service functions. Keep other settings as default, then click <strong>Save</strong>.</li></ol><img loading="lazy" height="727" width="757" src="'+qt+'" class="common_img" style="width:500px;"><ol start="8"><li>Click <strong>Devices</strong> to access device management.</li></ol><img loading="lazy" height="410" width="936" src="'+H+'" class="common_img" style="width:500px;"><ol start="9"><li>Click <strong>Link new device</strong>. Enter the <strong>6-digit device ID</strong> in the pop-up window, then click <strong>Link</strong>.</li></ol><img loading="lazy" height="248" width="964" src="'+U+'" class="common_img" style="width:500px;"><img loading="lazy" height="238" width="969" src="'+G+'" class="common_img" style="width:500px;"><ol start="10"><li>If binding is successful, <strong>Device added successfully</strong> is displayed. Select <strong>Open Source</strong>, then click <strong>Start Using</strong>.</li></ol><img loading="lazy" height="736" width="929" src="'+N+'" class="common_img" style="width:500px;"><ol start="11"><li>After successful binding, the module enters the MCP setup waiting interface. The current mode waits for an external controller to configure MCP for the large model. Since no external controller is connected, <strong>short-press</strong> <strong>Button A</strong> to enter the large model expression mode.</li></ol><img loading="lazy" height="441" width="441" src="'+K+'" class="common_img" style="width:300px;"><ol start="12"><li>Upon entering the large model expression mode, the module displays expressions. Network configuration and binding are now complete.</li></ol><img loading="lazy" height="441" width="441" src="'+l+'" class="common_img" style="width:300px;"><ol start="13"><li><strong>Short-press</strong> <strong>Button B</strong> to switch modes. The modes are described below:</li></ol><p>  </p><p>​ <strong>Expression Mode: Supports normal conversation. Dialogue messages are not displayed.</strong></p><img loading="lazy" height="441" width="441" src="'+l+'" class="common_img" style="width:300px;"><p>  </p><p>​ <strong>Image Transmission Mode: Normal conversation is not supported. Dialogue messages are not displayed.</strong></p><img loading="lazy" height="441" width="441" src="'+W+'" class="common_img" style="width:300px;"><p>  </p><p>​ <strong>Chat Mode: Supports normal conversation. Dialogue messages are displayed on the screen. Image recognition is supported.</strong></p><img loading="lazy" height="441" width="441" src="'+X+'" class="common_img" style="width:300px;"><h3 id="_2-1-5-free-chat" tabindex="-1">2.1.5 Free Chat <a class="header-anchor" href="#_2-1-5-free-chat" aria-label="Permalink to &quot;2.1.5 Free Chat&quot;">​</a></h3><p>After the module preparation steps are completed, <strong>press</strong> <strong>Button B twice</strong> to switch to chat mode. In chat mode, the module is activated by saying the <strong>wake word</strong> <strong>Hello Hiwonder</strong> or <strong>short-pressing Button A</strong>.</p><p>The module has built-in special functions that can be activated by voice commands during human-robot interaction. Refer to the following phrases to query all currently supported special functions:</p><p><strong>① What can it do? ② Introduce functions.</strong></p><p>  </p><p>Refer to the following phrases to activate corresponding special functions on the WonderMind Module:</p><img loading="lazy" height="441" width="441" src="'+F+'" class="common_img" style="width:300px;"><p>  </p><ol><li><strong>Weather Query</strong>: Check the weather in location.</li></ol><p>  </p><ol start="2"><li>News Broadcast: <strong>① Broadcast today&#39;s news. ② Introduce today&#39;s hot events</strong>.</li></ol><img loading="lazy" height="441" width="441" src="'+Z+'" class="common_img" style="width:300px;"><p>  </p><ol start="3"><li>Outfit Recommendation: <strong>Give an outfit recommendation for today.</strong></li></ol><img loading="lazy" height="441" width="441" src="'+Q+'" class="common_img" style="width:300px;"><p>  </p><ol start="4"><li>Joke Telling: <strong>① Tell a joke. ② Tell a joke to lighten the mood.</strong></li></ol><img loading="lazy" height="441" width="441" src="'+V+'" class="common_img" style="width:300px;"><p>  </p><ol start="5"><li>Horoscope Query: <strong>Check today&#39;s horoscope for zodiac sign.</strong></li></ol><img loading="lazy" height="441" width="441" src="'+J+'" class="common_img" style="width:300px;"><p>  </p><ol start="6"><li>Music Playback: <strong>Play a random song</strong>.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Lower the module volume before using music playback.</strong></p></div><img loading="lazy" height="441" width="441" src="'+Y+'" class="common_img" style="width:300px;"><h2 id="_2-2-controller-power-on-and-charging-instructions" tabindex="-1">2.2 Controller Power On and Charging Instructions <a class="header-anchor" href="#_2-2-controller-power-on-and-charging-instructions" aria-label="Permalink to &quot;2.2 Controller Power On and Charging Instructions&quot;">​</a></h2><h3 id="_2-2-1-powering-on" tabindex="-1">2.2.1 Powering On <a class="header-anchor" href="#_2-2-1-powering-on" aria-label="Permalink to &quot;2.2.1 Powering On&quot;">​</a></h3><p>Toggle the power switch. The power indicator on the controller illuminates, indicating successful startup.</p><img loading="lazy" height="1200" width="2020" src="'+$+'" class="common_img" style="width:500px;"><h3 id="_2-2-2-charging" tabindex="-1">2.2.2 Charging <a class="header-anchor" href="#_2-2-2-charging" aria-label="Permalink to &quot;2.2.2 Charging&quot;">​</a></h3><ol><li>Ensure the controller switch is set to <strong>OFF</strong>. Connect the Type-C cable to the controller charging port and to the charger.</li></ol><img loading="lazy" height="1200" width="1200" src="'+tt+'" class="common_img" style="width:400px;"><ol start="2"><li>The indicator displays the current charging status. All four white LEDs illuminate when fully charged. Disconnect the cable promptly after charging to avoid overcharging.</li></ol><img loading="lazy" height="2000" width="2000" src="'+et+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The power switch must be OFF during charging. Otherwise, the battery may not fully charge. Disconnect the charger and cable promptly after charging to prevent battery damage from overcharging.</strong></p></div><h2 id="_2-3-software-preparation" tabindex="-1">2.3 Software Preparation <a class="header-anchor" href="#_2-3-software-preparation" aria-label="Permalink to &quot;2.3 Software Preparation&quot;">​</a></h2><h3 id="_2-3-1-downloading-the-programming-software-package" tabindex="-1">2.3.1 Downloading the Programming Software Package <a class="header-anchor" href="#_2-3-1-downloading-the-programming-software-package" aria-label="Permalink to &quot;2.3.1 Downloading the Programming Software Package&quot;">​</a></h3><p><a href="https://k12.hiwonder.com.cn/download/pcSoftware?get_pc=1&amp;os=windows" target="_blank" rel="noreferrer">WonderLab Programming Platform Download(Windows)</a></p><img loading="lazy" height="1017" width="1920" src="'+it+'" class="common_img" style="width:800px;"><h3 id="_2-3-2-installing-wonderlab-programming-software" tabindex="-1">2.3.2 Installing WonderLab Programming Software <a class="header-anchor" href="#_2-3-2-installing-wonderlab-programming-software" aria-label="Permalink to &quot;2.3.2 Installing WonderLab Programming Software&quot;">​</a></h3><ol><li>Open the <strong>WonderLab setup.exe</strong> installation package.</li></ol><img loading="lazy" height="204" width="192" src="'+ot+'" class="common_img" style="width:80px;"><ol start="2"><li>Select the language, then click <strong>OK</strong>.</li></ol><img loading="lazy" height="162" width="349" src="'+at+'" class="common_img" style="width:350px;"><ol start="3"><li>Select the installation location, then click <strong>Next</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+st+'" class="common_img" style="width:500px;"><ol start="4"><li>Click <strong>Next</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+nt+'" class="common_img" style="width:500px;"><ol start="5"><li>Click <strong>Install</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+lt+'" class="common_img" style="width:500px;"><img loading="lazy" height="415" width="582" src="'+rt+'" class="common_img" style="width:500px;"><ol start="6"><li>After successful installation, click <strong>Finish</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+dt+'" class="common_img" style="width:500px;"><h2 id="_2-4-starter-projects" tabindex="-1">2.4 Starter Projects <a class="header-anchor" href="#_2-4-starter-projects" aria-label="Permalink to &quot;2.4 Starter Projects&quot;">​</a></h2><h3 id="_2-4-1-buzzer-alarm" tabindex="-1">2.4.1 Buzzer Alarm <a class="header-anchor" href="#_2-4-1-buzzer-alarm" aria-label="Permalink to &quot;2.4.1 Buzzer Alarm&quot;">​</a></h3><h4 id="_1-learning-objectives" tabindex="-1">(1) Learning Objectives <a class="header-anchor" href="#_1-learning-objectives" aria-label="Permalink to &quot;(1) Learning Objectives&quot;">​</a></h4><ul><li><p><strong>Knowledge Objectives</strong>: Understand basic operations of the WonderLab programming platform. Learn the function of the buzzer module on the AiBlock controller, sound generation principles, and parameters for volume, pitch, and beat. Master basic programming logic for main loops and button event triggers.</p></li><li><p><strong>Skill Objectives</strong>: Complete basic operations for creating new projects and adding controller extensions in the programming software. Independently build graphical programs for buzzer sound generation and volume adjustment. Master the complete workflow of program connection, upload, and debugging.</p></li><li><p><strong>Literacy Objectives</strong>: Develop preliminary programming thinking for hardware-software integration. Understand the function of event trigger mechanisms. Build foundational program debugging and hands-on implementation skills.</p></li></ul><h4 id="_2-adding-extensions" tabindex="-1">(2) Adding Extensions <a class="header-anchor" href="#_2-adding-extensions" aria-label="Permalink to &quot;(2)  Adding Extensions&quot;">​</a></h4><ul><li>Open the programming software and create a new project.</li></ul><img loading="lazy" height="1040" width="1920" src="'+At+'" class="common_img" style="width:800px;"><ul><li>Click the extensions button in the lower-left corner.</li></ul><img loading="lazy" height="1040" width="1920" src="'+St+'" class="common_img" style="width:800px;"><ul><li>Select <strong>AI Blocks Board</strong> under the <strong>Controller</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+jt+'" class="common_img" style="width:800px;"><h4 id="_3-core-blocks" tabindex="-1">(3) Core Blocks <a class="header-anchor" href="#_3-core-blocks" aria-label="Permalink to &quot;(3) Core Blocks&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Block</th><th style="text-align:left;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+gt+'" alt="" loading="lazy"></td><td style="text-align:left;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Program main loop container. Continuously executes internal code after power-on initialization completes.</td></tr><tr><td style="text-align:left;"><img src="'+mt+'" alt="" loading="lazy"></td><td style="text-align:left;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Drives the buzzer to play notes at specified pitch and beat. Runs in background mode without blocking subsequent program execution.</td></tr><tr><td style="text-align:left;"><img src="'+ct+'" alt="" loading="lazy"></td><td style="text-align:left;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Adjusts buzzer output volume. Value range 0 to 100. Higher values produce greater volume.</td></tr><tr><td style="text-align:left;"><img src="'+ht+'" alt="" loading="lazy"></td><td style="text-align:left;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Event-triggered block. Executes internally nested code when a corresponding button short-press is detected.</td></tr></tbody></table><h4 id="_4-program-description-and-upload" tabindex="-1">(4) Program Description and Upload <a class="header-anchor" href="#_4-program-description-and-upload" aria-label="Permalink to &quot;(4) Program Description and Upload&quot;">​</a></h4><ul><li><p>Complete Program</p><p>After power-on, the main loop runs continuously with non-stop prompt sound effects. The buttons use event-triggered mechanisms. Short-pressing the left and right buttons modifies the buzzer volume in real time, demonstrating dynamic parameter adjustment for output modules.</p></li></ul><img loading="lazy" height="618" width="715" src="'+It+'" class="common_img" style="width:600px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1YidlOU_m5IkNRXO5J-IIHQBPEjEh7tIQ?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><ul><li><p>Program Upload</p><p>Click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+i+'" class="common_img" style="width:800px;"><h3 id="_2-4-2-ultrasonic-distance-based-motor-control" tabindex="-1">2.4.2 Ultrasonic Distance-Based Motor Control <a class="header-anchor" href="#_2-4-2-ultrasonic-distance-based-motor-control" aria-label="Permalink to &quot;2.4.2 Ultrasonic Distance-Based Motor Control&quot;">​</a></h3><h4 id="_1-learning-objectives-1" tabindex="-1">(1) Learning Objectives <a class="header-anchor" href="#_1-learning-objectives-1" aria-label="Permalink to &quot;(1) Learning Objectives&quot;">​</a></h4><ul><li><strong>Knowledge Objectives</strong>: Understand the ultrasonic sensor ranging principle and data parameter meanings. Recognize the operating characteristics of the 360° block motor and 180° block servo. Master the foundational programming logic for distance judgment, sensor data reading, and actuator on / off control.</li><li><strong>Skill Objectives</strong>: Master standard wiring methods for the ultrasonic sensor with motors and servos. Independently add corresponding function extension modules. Proficiently build conditional judgment programs linking distance detection with power output. Complete program upload and function debugging.</li><li><strong>Literacy Objectives</strong>: Establish closed-loop programming thinking of &quot;environmental ranging perception, intelligent judgment, power execution.&quot; Develop logical analysis capabilities and hands-on STEAM practice for automatic device control based on environmental data.</li></ul><h4 id="_2-hardware-wiring" tabindex="-1">(2) Hardware Wiring <a class="header-anchor" href="#_2-hardware-wiring" aria-label="Permalink to &quot;(2) Hardware Wiring&quot;">​</a></h4><ul><li>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</li><li>Connect the 180° block servo to port <strong>S2</strong> of the controller using a 3-pin servo cable.</li><li>Connect the ultrasonic sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="1770" width="1826" src="'+Mt+'" class="common_img" style="width:500px;"><h4 id="_3-adding-extensions" tabindex="-1">(3) Adding Extensions <a class="header-anchor" href="#_3-adding-extensions" aria-label="Permalink to &quot;(3) Adding Extensions&quot;">​</a></h4><ul><li>Select <strong>Ultrasonic sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+Et+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> and <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+Lt+'" class="common_img" style="width:800px;"><h4 id="_4-core-blocks" tabindex="-1">(4) Core Blocks <a class="header-anchor" href="#_4-core-blocks" aria-label="Permalink to &quot;(4) Core Blocks&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Block</th><th style="text-align:left;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+pt+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+t+'" alt="" loading="lazy"></td><td style="text-align:left;">Initialize the ultrasonic sensor hardware interface.</td></tr><tr><td style="text-align:left;"><img src="'+ut+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+t+'" alt="" loading="lazy"></td><td style="text-align:left;">Retrieve obstacle distance data measured by the ultrasonic sensor. Unit: centimeters, cm.</td></tr><tr><td style="text-align:left;"><img src="'+yt+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+o+'" alt="" loading="lazy"></td><td style="text-align:left;">Control the 360° block motor on the specified port with a custom speed. Select forward or reverse rotation direction for continuous operation.</td></tr><tr><td style="text-align:left;"><img src="'+ft+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+o+'" alt="" loading="lazy"></td><td style="text-align:left;">Cut off output to the 360° block motor on the specified port, stopping rotation immediately.</td></tr><tr><td style="text-align:left;"><img src="'+_t+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+o+'" alt="" loading="lazy"></td><td style="text-align:left;">Control the 180° block servo on the specified port, rotating at a custom speed for a specified duration. Select no-delay mode to continue executing subsequent blocks without waiting for the servo movement to complete.</td></tr></tbody></table><h4 id="_5-program-description-and-upload" tabindex="-1">(5) Program Description and Upload <a class="header-anchor" href="#_5-program-description-and-upload" aria-label="Permalink to &quot;(5) Program Description and Upload&quot;">​</a></h4><ul><li><p>Complete Program</p><p>At startup, the ultrasonic sensor hardware interface is initialized to port A, and the servo initial position is set to 0°. The main program loop continuously detects the distance to objects ahead. If the distance exceeds 15 cm, motor <strong>S1</strong> maintains forward rotation at 50% speed. Otherwise, the motor stops, and servo <strong>S2</strong> rotates to 180° at 50% speed.</p></li></ul><img loading="lazy" height="542" width="638" src="'+Bt+'" class="common_img" style="width:600px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1YidlOU_m5IkNRXO5J-IIHQBPEjEh7tIQ?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><ul><li><p>Program Upload</p><p>Click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p></li></ul><p>​ <img loading="lazy" height="360" width="640" src="'+i+'" class="common_img" style="width:800px;"></p><h3 id="_2-4-3-light-responsive-temperature-and-humidity-display" tabindex="-1">2.4.3 Light-Responsive Temperature and Humidity Display <a class="header-anchor" href="#_2-4-3-light-responsive-temperature-and-humidity-display" aria-label="Permalink to &quot;2.4.3 Light-Responsive Temperature and Humidity Display&quot;">​</a></h3><h4 id="_1-learning-objectives-2" tabindex="-1">(1) Learning Objectives <a class="header-anchor" href="#_1-learning-objectives-2" aria-label="Permalink to &quot;(1) Learning Objectives&quot;">​</a></h4><ul><li><strong>Knowledge Objectives</strong>: Recognize the detection principles and value ranges of the light sensor and temperature-humidity sensor. Understand the output characteristics of the RGB light module and dot matrix display. Master programming logic for multi-environmental data detection, conditional judgment, visual display, and light linkage.</li><li><strong>Skill Objectives</strong>: Complete wiring and extension addition for environmental sensors with display and light modules. Independently build multi-environmental data collection and intelligent interaction programs. Achieve intelligent control of temperature-humidity display and light states based on light intensity. Advance multi-module collaborative programming and debugging capabilities.</li><li><strong>Literacy Objectives</strong>: Establish advanced programming thinking for multi-sensor environmental perception and multi-output module coordinated feedback. Understand the working principles of intelligent device environmental monitoring and state interaction. Develop data thinking and intelligent scenario innovation application capabilities.</li></ul><h4 id="_2-hardware-wiring-1" tabindex="-1">(2) Hardware Wiring <a class="header-anchor" href="#_2-hardware-wiring-1" aria-label="Permalink to &quot;(2) Hardware Wiring&quot;">​</a></h4><ul><li>Connect the light sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</li><li>Connect the temperature-humidity sensor to port <strong>B</strong> of the controller using a 4-pin module cable.</li><li>Connect the RGB light module to port <strong>C</strong> of the controller using a 4-pin module cable.</li><li>Connect the dot matrix module to port <strong>D</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="2020" width="2230" src="'+Ot+'" class="common_img" style="width:500px;"><h4 id="_3-adding-extensions-1" tabindex="-1">(3) Adding Extensions <a class="header-anchor" href="#_3-adding-extensions-1" aria-label="Permalink to &quot;(3) Adding Extensions&quot;">​</a></h4><ul><li><p>Select <strong>Light sensor</strong> and <strong>Temperature humidity sensor</strong> under the <strong>Input Module</strong> category.</p><img loading="lazy" height="1040" width="1920" src="'+Dt+'" class="common_img" style="width:800px;"></li><li><p>Select <strong>Dot matrix module</strong> and <strong>RGB module</strong> under the <strong>Output module</strong> category.</p></li></ul><img loading="lazy" height="1040" width="1920" src="'+Tt+'" class="common_img" style="width:800px;"><h4 id="_4-core-blocks-1" tabindex="-1">(4) Core Blocks <a class="header-anchor" href="#_4-core-blocks-1" aria-label="Permalink to &quot;(4) Core Blocks&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Block</th><th style="text-align:left;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+wt+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+t+'" alt="" loading="lazy"></td><td style="text-align:left;">Initialize the temperature-humidity sensor hardware interface.</td></tr><tr><td style="text-align:left;"><img src="'+bt+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+t+'" alt="" loading="lazy"></td><td style="text-align:left;">Read temperature or humidity values in real time.</td></tr><tr><td style="text-align:left;"><img src="'+Rt+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+t+'" alt="" loading="lazy"></td><td style="text-align:left;">Read light intensity value from the light sensor on the specified port. Value range 0 to 100. Brighter light produces higher values.</td></tr><tr><td style="text-align:left;"><img src="'+Ht+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+a+'" alt="" loading="lazy"></td><td style="text-align:left;">Control the dot matrix display on the specified port. Output specified text at coordinates (x, y). Select scroll or non-scroll mode. Refreshes screen content after execution.</td></tr><tr><td style="text-align:left;"><img src="'+Ut+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+a+'" alt="" loading="lazy"></td><td style="text-align:left;">Control the RGB light module on the specified port. Select a preset color to illuminate the light.</td></tr><tr><td style="text-align:left;"><img src="'+Gt+'" alt="" loading="lazy"></td><td style="text-align:left;"><img src="'+a+'" alt="" loading="lazy"></td><td style="text-align:left;">Turn off the RGB light module on the specified port. Cut off light output.</td></tr></tbody></table><h4 id="_5-program-description-and-upload-1" tabindex="-1">(5) Program Description and Upload <a class="header-anchor" href="#_5-program-description-and-upload-1" aria-label="Permalink to &quot;(5) Program Description and Upload&quot;">​</a></h4><ul><li><p>Complete Program</p><p>At startup, the temperature-humidity sensor hardware interface is initialized. The main program loop continuously monitors ambient light intensity. If the light value exceeds 70, the temperature value is displayed in real time on the dot matrix screen, and the RGB light is turned off. Otherwise, the humidity value is displayed in real time on the dot matrix screen, and the RGB light illuminates white.</p></li></ul><img loading="lazy" height="570" width="986" src="'+Nt+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1YidlOU_m5IkNRXO5J-IIHQBPEjEh7tIQ?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><ul><li>Program Upload</li></ul><p>Click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p><img loading="lazy" height="360" width="640" src="'+i+'" class="common_img" style="width:800px;">',214)])])}const ie=xt(Kt,[["render",Wt]]);export{ee as __pageData,ie as default};
